+        ? ReadonlySet<ReplaceRecur<TValue, TMarker, TReplacement>>
+        : TValue extends Set<infer TValue>
+          ? Set<ReplaceRecur<TValue, TMarker, TReplacement>>
+          : TValue extends readonly (infer TValue)[]
+            ? { readonly [TKey in keyof TValue]: ReplaceRecur<TValue[TKey], TMarker, TReplacement> }
+            : TValue extends object
+              ? { [TKey in keyof TValue]: ReplaceRecur<TValue[TKey], TMarker, TReplacement> }
+              : TValue;
