+    type: 'recursive',
+    reference: recursive,
+    expects: wrapped.expects,
+    async: false,
+    wrapped,
+    get '~standard'() {
+      return _getStandardProps(this);
+    },
+    '~run'(dataset, config) {
+      return wrapped['~run'](dataset, config) as OutputDataset<
+        RecursiveOutput<TSchema>,
+        InferIssue<TSchema>
+      >;
+    },
+  };
+  return recursiveSchema;
+}
+
+/**
+ * Creates an async recursive schema.
+ *
+ * @param schema The schema that contains recursive placeholders.
+ *
+ * @returns A recursive schema.
+ */
+// @__NO_SIDE_EFFECTS__
+export function recursiveAsync<const TSchema extends RecurSchemaLike>(
+  schema: TSchema
+): RecursiveSchemaAsync<TSchema> {
+  let recursiveSchema: RecursiveSchemaAsync<TSchema>;
+  const wrapped = _resolveRecur(schema, () => recursiveSchema) as TSchema;
+  recursiveSchema = {
+    kind: 'schema',
+    type: 'recursive',
+    reference: recursiveAsync,
+    expects: wrapped.expects,
+    async: true,
+    wrapped,
+    get '~standard'() {
+      return _getStandardProps(this);
+    },
+    async '~run'(dataset, config) {
+      return (await wrapped['~run'](dataset, config)) as OutputDataset<
+        RecursiveOutput<TSchema>,
+        InferIssue<TSchema>
+      >;
+    },
+  };
+  return recursiveSchema;
+}
+
+function _resolveRecur<TValue>(value: TValue, getRecur: () => RecurSchemaLike): TValue {
+  if (value === Recur) {
+    return getRecur() as TValue;
+  }
+  if (Array.isArray(value)) {
+    return value.map((item) => _resolveRecur(item, getRecur)) as TValue;
+  }
+  if (value && typeof value === 'object') {
+    if ('kind' in value && (value.kind === 'schema' || value.kind === 'validation' || value.kind === 'transformation' || value.kind === 'metadata')) {
+      const schema = value as { readonly pipe?: readonly unknown[]; readonly async?: boolean };
+      if (schema.pipe) {
+        const items = schema.pipe.map((item) => _resolveRecur(item, getRecur));
+        return (schema.async ? pipeAsync : pipe)(...items as [never, ...never[]]) as TValue;
+      }
+    }
+    const descriptors = Object.getOwnPropertyDescriptors(value);
+    for (const key of Object.keys(descriptors)) {
+      const descriptor = descriptors[key];
+      if ('value' in descriptor) {
+        descriptor.value = _resolveRecur(descriptor.value, getRecur);
+      }
+    }
+    return Object.create(Object.getPrototypeOf(value), descriptors);
+  }
+  return value;
+}
